// TH16 v1.00a Stage 2 Boss Card 3: 尽符「マウンテンマーダー」
// Source: st02bs.ecl.txt BossCard3 632-698; deps BossCard3_at 700-742, BossCard3_at2 744-785.
// Source t=0 is card frame ~OPENING_BUFFER; the 1800-frame window ends at source t=1800.

const TIME_LIMIT: int = 1924;        // 120 opening + 1800 source window + 4 startup
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 16;

const TH16_DAGGER: int = 688;        // source etSprite type 21, base radius 6
const TH16_BIG_BALL: int = 640;      // source etSprite type 18, base radius 8.5
const COLOR_1: int = 1;

// Source angles in BAM (a*65536/2pi).
const AT_BASE_STEP: int = 40503;     // 3.883222 rad
const AT_SPREAD_3DEG: int = 546;     // 0.05236 rad (E/N/H)
const AT_SPREAD_L: int = 291;        // 0.027925 rad (L)
const AT2_BASE_START: int = -16384;  // -1.570796 rad
const AT2_BASE_STEP: int = -1820;    // -0.174533 rad
const AT2_LAYER_STEP: int = 546;     // 0.05235988 rad (layer twist, unused at M=1)

xformdef DAGGER_DECEL {
    // Source EX: ANIM(0x2) a=1 -> birth retreat 4*3.0=12px, folded into sh_dist 24-12=12.
    // WAIT(0x80000000) a=40; VELTIME(0x200000) a=40, r=1.0, angle preserved (s=-999999).
    wait(40);
    step_speed(1fx, 40 + 65536 * EASE_LINEAR);
}

// moveRand(50, 4, 1.0): speed(k)=1-k/50 for k=1..50, fixed direction per call.
// moveLimit(0,144,240,64): bounds x[-120,120], y[112,176]; direction inner region
// x±60, y128..160 (center ± width/4, height/4), per movement.md.
sub mv_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 50 { speed = (50 - k) as fx / 50; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 112fx { ny = 112fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mv_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mv_arm_next_step();
}

sub mv_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mv_arm_next_step();
    }
}

sub mv_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 128fx {
        if a < 0 { a = -a; }
    } else if $self_y > 160fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard (epsilon 0.05 rad).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mv_begin(a as angle);
}

// BossCard3_at: 180 emissions, 2 frames apart; fixed fan of N, base rotates +3.883222 rad.
sub dagger_wave(spread: int) {
    var base: int = 0;
    for i in 0..180 {
        sh_angle(0, base as angle, spread as angle);
        sh_fire(0);
        base = base + AT_BASE_STEP;
        wait(2);
    }
}

// BossCard3_at2 (!HL async): fixed ring of 1 (L: 2), every 4 frames, base rotates -10 deg.
// Source runs 180000 iterations (720000 frames); the 1800-frame interrupt stops it at 420 shots.
async sub at2_stream() {
    var count: int = 1;
    if global(GVAR_RANK) >= RANK_LUNATIC { count = 2; }
    sh_reset(0);
    sh_sprite(0, TH16_BIG_BALL, COLOR_1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, count, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, 74fx);                // etDist 80 - 4*1.5 ANIM retreat
    var base: int = AT2_BASE_START;
    for i in 0..420 {
        sh_angle(0, base as angle, AT2_LAYER_STEP as angle);
        sh_fire(0);
        base = base + AT2_BASE_STEP;
        wait(4);
    }
}

async sub attack_pattern() {
    wait(OPENING_BUFFER);

    // Source t=0: movePosTime(60,4,0,144); moveLimit(0,144,240,64) is applied in mv_*.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    // Source +60/+120: nop/anmPlay/playSound only (omitted); first wave at source t=120.
    wait(120);

    if global(GVAR_RANK) >= RANK_HARD {
        spawn at2_stream();
    }

    var count: int = 1;
    var spread: int = AT_SPREAD_3DEG;
    if global(GVAR_RANK) >= RANK_NORMAL { count = 3; }
    if global(GVAR_RANK) >= RANK_LUNATIC { count = 5; spread = AT_SPREAD_L; }
    sh_reset(0);
    sh_sprite(0, TH16_DAGGER, COLOR_1);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, count, 1);
    sh_speed(0, 3fx, 0fx);
    sh_dist(0, 12fx);
    sh_xform(0, DAGGER_DECEL);

    // 4 full source cycles fit before setInterrupt(0,0,1800): 120 + 4*420 = 1800.
    for cycle in 0..4 {
        dagger_wave(spread);
        mv_rand();
        mv_wait(60);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);                // source setHitbox(48,48) circle -> r=24
    set_hurtbox(20fx);               // source setHurtbox(40,40) circle -> r=20
    spell_begin(0, SPELL_ID, attack_pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    // Boss() home position is (0,128); BossCard3 itself moves to (0,144) over 60 frames.
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
